def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    best = None
    for r in range(1, H):
        for c in range(1, W):
            C = g[r, c]
            if C == bg:
                continue
            if np.all(g[r, :c + 1] == C) and np.all(g[:r + 1, c] == C) and not np.any(g[:r, :c] == C):
                if best is None or r + c < best[0] + best[1]:
                    best = (r, c, C)
    h, w, C = best
    motif = g[:h, :w]
    cols = [v for v in np.unique(motif) if v != bg]
    A = cols[0] if cols else C
    mask = motif != bg
    out = np.full_like(g, bg)
    emit(out.copy(), "Clear the grid to background; the motif (%dx%d, colour %d) and frame colour %d are remembered." % (h, w, A, C))
    nby = (H + h - 1) // h
    nbx = (W + w - 1) // w
    for bi in range(nby):
        for bj in range(nbx):
            col = A if mask[bi % h, bj % w] else C
            for dy in range(h):
                for dx in range(w):
                    y, x = bi * h + dy, bj * w + dx
                    if y < H and x < W and mask[dy, dx]:
                        out[y, x] = col
        emit(out.copy(), "Stamp block row %d: each block copies the motif shape, coloured %d where the motif cell (row %d mod %d) is set, else frame colour %d." % (bi, A, bi, h, C))
    emit(out.copy(), "Final self-similar tiling.")
    return out
